pragma solidity ^0.8.36;
type Currency is address;
contract TupleCleanup {
    function choose(Currency a, Currency b, bool yes) external pure returns (Currency, Currency) {
        return yes ? (a, b) : (b, a);
    }
    function raw(bool yes) external pure returns (uint256, uint256) {
        Currency a = Currency.wrap(address(1));
        Currency b = Currency.wrap(address(2));
        assembly { a := not(0) b := or(shl(160, 1), 2) }
        (a, b) = yes ? (a, b) : (b, a);
        assembly { mstore(0, a) mstore(32, b) return(0, 64) }
    }
}
